			Identity mission = ((IEntity)character).Identity;
			ReplaceInstance(array, 1985636618, ((Identity)(ref mission)).Instance);
			ReplaceInstance(array, 1431734586, instance);
			byte[] array2 = HexToBytes("0136000A0001003500000DB6765A690A212C487A0000C350765A690A0000000001000000000000DAC35556893A0000000000000000");
			mission = ((IEntity)character).Identity;
			ReplaceInstance(array2, 1985636618, ((Identity)(ref mission)).Instance);
			ReplaceInstance(array2, 1431734586, instance);
