	private static bool TryResolveMissionInstance(string questId, out int instance)
	{
		instance = 0;
		if (string.IsNullOrWhiteSpace(questId))
		{
			return false;
		}
		string text = questId.Trim();
		int num = text.LastIndexOf(':');
		string s = ((num >= 0) ? text.Substring(num + 1) : text);
		return int.TryParse(s, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out instance);
	}

	private static bool TrySendRaw(ICharacter character, string hex)
	{
		//IL_003c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0041: Unknown result type (might be due to invalid IL or missing references)
		if (!CanSend(character) || string.IsNullOrWhiteSpace(hex))
		{
			return false;
		}
		try
		{
			ZoneClient zoneClient = ((IDynel)character).Controller.Client as ZoneClient;
			byte[] array = HexToBytes(hex);
			Identity identity = ((IEntity)character).Identity;
			ReplaceInstance(array, 1985636618, ((Identity)(ref identity)).Instance);
			PatchMissionExpiry(array, zoneClient);
			zoneClient.EnqueueOutboundCompressedBuffer(array);
			return true;
		}
		catch (Exception ex)
		{
			LogUtil.Debug((DebugInfoDetail)512, "THRAK_GARDEN_KEY QuestFullUpdate failed: " + ex.Message);
			return false;
		}
	}

	private static void PatchMissionExpiry(byte[] packet, ZoneClient client)
	{
		if (packet == null || client == null)
		{
			return;
		}
		double num = (DateTime.UtcNow - client.LastGameTimeSyncUtc).TotalSeconds;
		if (num < 0.0)
		{
			num = 0.0;
		}
		if (num > 43200.0)
		{
			num = 0.0;
			client.LastGameTimeSyncUtc = DateTime.UtcNow;
		}
		long num2 = 1201445827 + (long)num;
		long num3 = num2 + 43200;
		for (int i = 0; i + 4 <= packet.Length; i++)
		{
			int num4 = (packet[i] << 24) | (packet[i + 1] << 16) | (packet[i + 2] << 8) | packet[i + 3];
			if ((num4 & -65536) == 1786970112)
			{
				WriteInt32BigEndian(packet, i, (int)num3);
				break;
			}
		}
	}

	private static void WriteInt32BigEndian(byte[] packet, int offset, int value)
	{
		packet[offset] = (byte)(value >> 24);
		packet[offset + 1] = (byte)(value >> 16);
		packet[offset + 2] = (byte)(value >> 8);
		packet[offset + 3] = (byte)value;
	}

	private static bool CanSend(ICharacter character)
	{
		return character != null && ((IDynel)character).Controller != null && ((IDynel)character).Controller.Client is ZoneClient;
	}

	private static void ReplaceInstance(byte[] packet, int from, int to)
	{
		byte b = (byte)(from >> 24);
		byte b2 = (byte)(from >> 16);
		byte b3 = (byte)(from >> 8);
		byte b4 = (byte)from;
		for (int i = 0; i + 4 <= packet.Length; i++)
		{
			if (packet[i] == b && packet[i + 1] == b2 && packet[i + 2] == b3 && packet[i + 3] == b4)
			{
				packet[i] = (byte)(to >> 24);
				packet[i + 1] = (byte)(to >> 16);
				packet[i + 2] = (byte)(to >> 8);
				packet[i + 3] = (byte)to;
				i += 3;
			}
		}
	}

	private static byte[] HexToBytes(string hex)
	{
		int num = hex.Length / 2;
		byte[] array = new byte[num];
		for (int i = 0; i < num; i++)
		{
			array[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
		}
		return array;
	}
